package sigepac.mvc.modelos;
import sigepac.mvc.configuracion.ConexionMvc; import java.sql.*; import java.util.*;
public class ModeloNegocio implements sigepac.mvc.modelos.contratos.IModeloNegocio {
 private Map<String,Object> map(ResultSet r)throws SQLException{Map<String,Object> m=new HashMap<>();m.put("id_negocio",r.getInt("id_negocio"));m.put("id_usuario",r.getInt("id_usuario"));m.put("nombre",r.getString("nombre"));m.put("local_numero",r.getString("local_numero"));m.put("estado",r.getString("estado"));m.put("propietario",r.getString("propietario"));return m;}
 private static final String SELECT="SELECT n.*,CONCAT(u.nombre,' ',u.apellido) propietario FROM negocios n JOIN usuarios u ON u.id_usuario=n.id_usuario";
 public Map<String,Object> buscarPorId(int id){try(Connection c=ConexionMvc.abrir();PreparedStatement p=c.prepareStatement(SELECT+" WHERE n.id_negocio=? AND n.estado='ACTIVO' FOR UPDATE")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}catch(SQLException e){throw ConexionMvc.fallo(e);}}
 public List<Map<String,Object>> obtenerTodos(){List<Map<String,Object>> a=new ArrayList<>();try(Connection c=ConexionMvc.abrir();Statement s=c.createStatement();ResultSet r=s.executeQuery(SELECT+" WHERE n.estado='ACTIVO' ORDER BY n.id_negocio")){while(r.next())a.add(map(r));return a;}catch(SQLException e){throw ConexionMvc.fallo(e);}}
 public boolean crear(int id,String nombre,String local){try(Connection c=ConexionMvc.abrir();PreparedStatement p=c.prepareStatement("INSERT INTO negocios(id_usuario,nombre,local_numero,estado) VALUES(?,?,?,'ACTIVO')")){p.setInt(1,id);p.setString(2,nombre);p.setString(3,local);return p.executeUpdate()==1;}catch(SQLIntegrityConstraintViolationException e){return false;}catch(SQLException e){throw ConexionMvc.fallo(e);}}
 public boolean actualizar(int id,String nombre,String local,String estado){try(Connection c=ConexionMvc.abrir();PreparedStatement p=c.prepareStatement("UPDATE negocios SET nombre=?,local_numero=?,estado=? WHERE id_negocio=?")){p.setString(1,nombre);p.setString(2,local);p.setString(3,estado);p.setInt(4,id);return p.executeUpdate()>0;}catch(SQLException e){throw ConexionMvc.fallo(e);}}
 public boolean eliminar(int id){try(Connection c=ConexionMvc.abrir();PreparedStatement p=c.prepareStatement("UPDATE negocios SET estado='INACTIVO' WHERE id_negocio=?")){p.setInt(1,id);return p.executeUpdate()>0;}catch(SQLException e){throw ConexionMvc.fallo(e);}}
}
